  ref('acc','Non-Uniform ACC Circuit Lower Bounds','Ryan Williams',2011,'https://people.csail.mit.edu/rrw/acc-lbs-journal-final.pdf','CCC 2011 result; author manuscript of the subsequent journal version, abstract and main theorems'),
